<?php require_once __DIR__.'/includes/auth.php'; require_login(['admin']);
$pdo=db();
$stats=$pdo->query("SELECT COUNT(*) total, SUM(CASE WHEN s.stage_name LIKE 'Released%' THEN 1 ELSE 0 END) released, SUM(CASE WHEN s.stage_name='With HOD' THEN 1 ELSE 0 END) hod, SUM(CASE WHEN s.stage_name='Sent to Dean' THEN 1 ELSE 0 END) dean FROM result_records r JOIN status_stages s ON s.id=r.current_stage_id")->fetch();
$overdue=(int)$pdo->query("SELECT COUNT(*) FROM result_records r JOIN status_stages s ON s.id=r.current_stage_id WHERE s.delay_days>0 AND TIMESTAMPDIFF(DAY,r.current_since,NOW())>s.delay_days")->fetchColumn();
$recent=$pdo->query("SELECT r.id,r.public_token,r.session_name,r.current_since,c.course_code,c.course_title,c.level,s.stage_name,o.office_name FROM result_records r JOIN courses c ON c.id=r.course_id JOIN status_stages s ON s.id=r.current_stage_id LEFT JOIN offices o ON o.id=r.current_office_id ORDER BY r.updated_at DESC LIMIT 12")->fetchAll();
$stageRows=$pdo->query("SELECT s.stage_name,COUNT(r.id) total FROM status_stages s LEFT JOIN result_records r ON r.current_stage_id=s.id WHERE s.stage_order BETWEEN 1 AND 7 GROUP BY s.id ORDER BY s.stage_order")->fetchAll();
$pageTitle='Admin Dashboard | IFT'; require __DIR__.'/includes/header.php'; ?>
<body class="portal-page"><header class="portal-header"><div class="portal-brand"><img src="assets/naits-logo.png"><div><strong>IFT Result Tracking</strong><span>Secretary / Admin Portal</span></div></div><button class="portal-menu" type="button" aria-expanded="false" aria-controls="sidebar" aria-label="Open menu">☰</button><div class="portal-user"><span class="avatar"><?=e(initials(current_user()['name']))?></span><div><strong><?=e(current_user()['name'])?></strong><small>Secretary / Admin</small></div><a href="index.php">Public Site</a></div></header><aside class="sidebar" id="sidebar"><nav><a class="active" href="admin-dashboard.php">▦ Dashboard</a><a href="record.php">＋ New Result</a><a href="handover.php">⇄ Handover</a><a href="courses.php">▤ Courses</a><a href="reports.php">▤ Reports</a><a href="activity-log.php">◷ Activity Log</a><hr><a href="index.php">↗ Public Site</a><a href="logout.php">↪ Sign Out</a></nav></aside><main class="portal-main"><div class="page-title"><div><span class="kicker">OVERVIEW</span><h1>Result Tracking Dashboard</h1><p>Monitor every physical result and its current location.</p></div><a class="primary-btn button-link" href="record.php">＋ Record Received Result</a></div><section class="stat-grid"><article class="stat-card"><span>All Results</span><strong><?=e($stats['total']??0)?></strong><small>All tracked records</small></article><article class="stat-card"><span>With HOD</span><strong><?=e($stats['hod']??0)?></strong><small>Currently at HOD stage</small></article><article class="stat-card warning"><span>With Dean</span><strong><?=e($stats['dean']??0)?></strong><small>Awaiting Dean action</small></article><article class="stat-card success"><span>Released</span><strong><?=e($stats['released']??0)?></strong><small>Completed results</small></article></section><section class="panel dashboard-panel"><div class="panel-head"><div><span class="kicker">RECENT MOVEMENT</span><h2>Results currently being tracked</h2></div><a href="reports.php">View reports →</a></div><div class="table-wrap"><table><thead><tr><th>Course</th><th>Level</th><th>Session</th><th>Current Stage</th><th>Office</th><th>Since</th><th></th></tr></thead><tbody><?php if(!$recent):?><tr><td colspan="7">No result records yet. <a href="record.php">Record the first result.</a></td></tr><?php else: foreach($recent as $r):?><tr><td><strong><?=e($r['course_code'])?></strong><small><?=e($r['course_title'])?></small></td><td><?=e($r['level'])?></td><td><?=e($r['session_name'])?></td><td><span class="table-status <?=e(stage_badge_class($r['stage_name']))?>"><?=e($r['stage_name'])?></span></td><td><?=e($r['office_name']??'—')?></td><td><?=e(date('d M, H:i',strtotime($r['current_since'])))?></td><td><a class="table-link" href="public-tracking.php?token=<?=e($r['public_token'])?>">View</a></td></tr><?php endforeach; endif;?></tbody></table></div></section><section class="dashboard-bottom"><div class="panel"><div class="panel-head"><div><span class="kicker">STAGE BREAKDOWN</span><h2>Where results are</h2></div></div><div class="bars"><?php $max=max(array_column($stageRows,'total') ?: [1]);foreach($stageRows as $sr):?><div><span><?=e($sr['stage_name'])?> <b><?=e($sr['total'])?></b></span><i><em style="width:<?=($max?round($sr['total']/$max*100):0)?>%"></em></i></div><?php endforeach;?></div></div><div class="panel alert-panel"><div class="panel-head"><div><span class="kicker">DELAY ALERTS</span><h2>Needs attention</h2></div><span class="alert-count"><?=e($overdue)?></span></div><p>Results beyond the configured stage delay threshold are shown here.</p><a href="reports.php">Review pending results →</a></div></section></main><?php require __DIR__.'/includes/footer.php'; ?>
